namespace Eccube\Repository;

use Doctrine\ORM\NonUniqueResultException;
use Doctrine\ORM\NoResultException;
use Doctrine\Persistence\ManagerRegistry as RegistryInterface;
use Eccube\Entity\Customer;
use Eccube\Entity\MailHistory;

/**
 * MailHistoryRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 *
 * @extends AbstractRepository<MailHistory>
 */
class MailHistoryRepository extends AbstractRepository
{
    /**
     * MailHistoryRepository constructor.
     */
    public function __construct(RegistryInterface $registry)
    {
        parent::__construct($registry, MailHistory::class);
    }

    /**
     * @return MailHistory
     *
     * @throws \Exception
     * @throws NoResultException
     * @throws NonUniqueResultException
     */
    public function getByCustomerAndId(Customer $Customer, int $id): MailHistory
    {
        $qb = $this->createQueryBuilder('mh')
            ->leftJoin('mh.Order', 'o')
            ->where('mh.id = :id AND o.Customer = :Customer');

        /** @var MailHistory $MailHistory */
        $MailHistory = $qb
            ->getQuery()
            ->setParameters([
                'id' => $id,
                'Customer' => $Customer,
            ])
            ->getSingleResult();

        return $MailHistory;
    }
}
